import docx
from docx.oxml.ns import qn
d = docx.Document("Thelbridge_Materials_Acceptance_Record_TEMPLATE.docx")

def sname(p):
    try:
        return p.style.name if p.style is not None else "(none)"
    except Exception:
        return "(err)"

print("=== PARAGRAPHS (idx | style | text) ===")
for i,p in enumerate(d.paragraphs):
    print(f"[{i:03d}] <{sname(p)}> {p.text!r}")

print("\n=== TABLES ===")
for ti,t in enumerate(d.tables):
    print(f"--- TABLE {ti}  rows={len(t.rows)} cols={len(t.columns)} ---")
    for ri,r in enumerate(t.rows):
        cells = [c.text for c in r.cells]
        print(f"  row{ri}: {cells}")

print("\n=== SECTIONS / MARGINS ===")
for s in d.sections:
    print('page w/h EMU', s.page_width, s.page_height, 'margins L/R/T/B', s.left_margin, s.right_margin, s.top_margin, s.bottom_margin)
    print('orientation', s.orientation)

# Inspect run-level formatting of a few key paragraphs
print("\n=== RUN DETAILS for first ~10 non-empty paras ===")
cnt=0
for i,p in enumerate(d.paragraphs):
    if p.text.strip()!='' and cnt<25:
        for r in p.runs:
            print(f"[{i:03d}] bold={r.bold} italic={r.italic} underline={r.underline} size={r.font.size} name={r.font.name} | {r.text!r}")
        cnt+=1
EOF

